javascript:
frappe.ready(function() {
    $('button[name="submit"]').on('click', function() {
        var firstName = $('input[name="firstname"]').val();
        var lastName = $('input[name="lastname"]').val();
        var email = $('input[name="email"]').val();
        var phone=$('input[name="phone"]').val();
        var shipmentType = $('select[name="custom_type_of_shipment"]').val();
        var TransportationMedium = $('select[name="custom_transportation_medium"]').val();
        var ShipmentTypes = $('select[name="custom_shipment_type"]').val();
        var Freight_Weight =$('input[name="freight_weight"]').val();
        var origin_country=$('select[name="or_country"]').val();
        var origin_state=$('input[name="or_state"]').val();
        var origin_city=$('input[name="or_city"]').val();
        var origin_pincode=$('input[name="or_pincode"]').val();
        var destination_country=$('select[name="des_country_name"]').val();
        var destination_state=$('input[name="des_state"]').val();
        var destination_city=$('input[name="des_city"]').val();
        var destination_pincode=$('input[name="des_pincode"]').val();
        
        if (!firstName ) {
            frappe.msgprint("Please fill in all fields.");
            return;
        }

        frappe.call({
            method: "frappe.client.insert",
            args: {
                doc: {
                    doctype: "Lead",
                    
                    first_name: firstName,
                    last_name: lastName,
                    email_id: email,
                    phone:phone,
                    custom_type_of_shipment: shipmentType,
                    custom_transportation_medium:TransportationMedium,
                    custom_shipment_type:ShipmentTypes,
                    custom_freight_weight_expected:Freight_Weight,
                    custom_origin_location:[
                        {
                        country: origin_country,
                        state:origin_state,
                        city: origin_city,
                        pincode:origin_pincode
                        }
                        ],
                    custom_destination_location:[
                        {
                        country: destination_country,
                        state:destination_state,
                        city: destination_city,
                        pincode:destination_pincode
                        }
                        ]
                    // custom_origin_location:origin_country,
                    // custom_origin_location:frappe._dict({
                    //     'country': 'origin_country',
                    //     'state': 'origin_state',
                    //     'city': 'origin_city',
                    //     'pincode':'origin_pincode'
                    //     })
                    
                    }
                   
            },
            callback: function() {
                frappe.msgprint("Lead Created ")
            }
        });
    });
});

